observation.command:
cat > /etc/nginx/sites-available/daexp <<'EOF'
server {
    listen 8080 default_server;
    listen [::]:8080 default_server;
    root /workspace;
    index index.html;
    server_name _;
    location / {
        try_files $uri $uri/ =404;
    }
}
EOF
rm -f /etc/nginx/sites-enabled/default
ln -sf /etc/nginx/sites-available/daexp /etc/nginx/sites-enabled/daexp
nginx -t 2>&1
nginx 2>&1
sleep 2
curl -s -o /dev/null -w "index.html HTTP %{http_code}\n" http://localhost:8080/index.html
curl -s -o /dev/null -w "src css HTTP %{http_code}\n" http://localhost:8080/src/css/dataExplorer.css
curl -s -o /dev/null -w "config HTTP %{http_code}\n" http://localhost:8080/config/baseConfig.json
curl -s -o /dev/null -w "externalPackages HTTP %{http_code}\n" http://localhost:8080/externalPackages/materialize/materialize.css
